def coinChange(coins: list[int], amount: int) -> int:
    unique_coins = sorted(list(set(coins)))
    best = [float('inf')]

    def search(rem, count):
        if rem == 0:
            if count < best[0]:
                best[0] = count
            return
        for c in unique_coins:
            if c <= rem and count + 1 < best[0]:
                search(rem - c, count + 1)

    search(amount, 0)
    return best[0] if best[0] != float('inf') else -1

